CREATE TABLE IF NOT EXISTS economic_execution_gate (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), decision_id uuid NOT NULL, profile_id uuid NOT NULL, approval_id uuid NOT NULL, execution_key text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'queued', requested_by text NOT NULL, executed_by text, cancellation_reason text, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz);
CREATE TABLE IF NOT EXISTS economic_execution_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), execution_id uuid NOT NULL, decision_id uuid NOT NULL, profile_id uuid NOT NULL, event_type text NOT NULL, actor_id text NOT NULL, from_status text, to_status text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_execution_gate_decision ON economic_execution_gate(decision_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_execution_events_execution ON economic_execution_events(execution_id,created_at DESC);